    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ActionBase actions:
                Actions ??= [];
                if (!Actions.Contains(actions))
                {
                    Actions = [..Actions, actions];
                    ModifiedParameters[nameof(Actions)] = Actions;
                }
                
                return true;
            case TimeSliderStops stops:
                if (stops != Stops)
                {
                    Stops = stops;
                    ModifiedParameters[nameof(Stops)] = Stops;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ActionBase actions:
                Actions = Actions?.Where(a => a != actions).ToList();
                ModifiedParameters[nameof(Actions)] = Actions;
                return true;
            case TimeSliderStops _:
                Stops = null;
                ModifiedParameters[nameof(Stops)] = Stops;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Actions is not null)
        {
            foreach (ActionBase child in Actions)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        Stops?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
